CREATE TABLE cafes (id integer PRIMARY KEY, name text NOT NULL, address text NOT NULL, working_hours text NOT NULL, phone text NOT NULL, image_key text NOT NULL, active boolean NOT NULL DEFAULT true);
CREATE TABLE users (id text PRIMARY KEY, email text NOT NULL UNIQUE CHECK(email=lower(email)), name text NOT NULL, password_hash text NOT NULL, role text NOT NULL DEFAULT 'customer' CHECK(role IN('customer','staff','admin')), cafe_id integer REFERENCES cafes(id), qualifying_orders integer NOT NULL DEFAULT 0 CHECK(qualifying_orders>=0), created_at timestamptz NOT NULL DEFAULT now(), CHECK(role<>'staff' OR cafe_id IS NOT NULL));
CREATE INDEX users_cafe_idx ON users(cafe_id);
CREATE TABLE sessions (token_hash text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX sessions_user_idx ON sessions(user_id);
CREATE INDEX sessions_expiry_idx ON sessions(expires_at);
CREATE TABLE products (id integer PRIMARY KEY CHECK(id>0), document jsonb NOT NULL CHECK(jsonb_typeof(document)='object'));
CREATE TABLE product_availability (cafe_id integer NOT NULL REFERENCES cafes(id), product_id integer NOT NULL REFERENCES products(id), available boolean NOT NULL DEFAULT true, PRIMARY KEY(cafe_id,product_id));
CREATE INDEX availability_product_idx ON product_availability(product_id);
CREATE TABLE addons (id text PRIMARY KEY, document jsonb NOT NULL CHECK(jsonb_typeof(document)='object'));
CREATE TABLE stories (id text PRIMARY KEY, document jsonb NOT NULL CHECK(jsonb_typeof(document)='object'));
CREATE TABLE quotes (id text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id), cafe_id integer NOT NULL REFERENCES cafes(id), request jsonb NOT NULL, snapshot jsonb NOT NULL, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX quotes_user_idx ON quotes(user_id);
CREATE INDEX quotes_cafe_idx ON quotes(cafe_id);
CREATE INDEX quotes_expiry_idx ON quotes(expires_at);
CREATE SEQUENCE order_number_seq START 1000;
CREATE TABLE orders (id text PRIMARY KEY, sequence bigint NOT NULL UNIQUE DEFAULT nextval('order_number_seq'), user_id text NOT NULL REFERENCES users(id), cafe_id integer NOT NULL REFERENCES cafes(id), quote_id text NOT NULL UNIQUE REFERENCES quotes(id), idempotency_key text NOT NULL, request_hash text NOT NULL, status text NOT NULL DEFAULT 'created' CHECK(status IN('created','accepted','preparing','ready','completed','cancelled')), payment_status text NOT NULL DEFAULT 'unpaid' CHECK(payment_status IN('unpaid','paid')), subtotal integer NOT NULL CHECK(subtotal>=0), discount_percent integer NOT NULL CHECK(discount_percent IN(3,5,7,10)), discount integer NOT NULL CHECK(discount>=0), total integer NOT NULL CHECK(total=subtotal-discount AND total>=0), comment text NOT NULL DEFAULT '', qr_token text NOT NULL UNIQUE, qr_expires_at timestamptz NOT NULL, qr_used_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,idempotency_key), CHECK(status<>'completed' OR payment_status='paid'));
CREATE INDEX orders_user_history_idx ON orders(user_id,sequence DESC);
CREATE INDEX orders_cafe_queue_idx ON orders(cafe_id,status,sequence DESC);
CREATE TABLE order_items (order_id text NOT NULL REFERENCES orders(id) ON DELETE CASCADE, position integer NOT NULL CHECK(position>=0), snapshot jsonb NOT NULL, PRIMARY KEY(order_id,position));
CREATE TABLE loyalty_ledger (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, user_id text NOT NULL REFERENCES users(id), order_id text NOT NULL UNIQUE REFERENCES orders(id), receipt_delta integer NOT NULL CHECK(receipt_delta=1), created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX ledger_user_idx ON loyalty_ledger(user_id,id);
CREATE TABLE order_events (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, order_id text NOT NULL REFERENCES orders(id), actor_id text NOT NULL REFERENCES users(id), event text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX events_order_idx ON order_events(order_id,id);
